#include "editor.hpp"
#include <obs.h>
#include <QPainter>
#include <QPainterPath>
#include <QMouseEvent>
#include <QWheelEvent>
#include <QKeyEvent>
#include <QApplication>
#include <algorithm>
#include <cmath>
using namespace spatial;
namespace {QString u(const char*s){return QString::fromUtf8(s);}constexpr int labelWidth=180,rowHeight=27,header=32;
bool same(const KeyRef&a,const KeyRef&b){return a.object==b.object&&a.parameter==b.parameter&&a.time==b.time;}}
TimelineWidget::TimelineWidget(StageModel*m,QWidget*p):QWidget(p),model(m){setObjectName("spatial.timeline32");setMinimumHeight(220);setMinimumWidth(380);setFocusPolicy(Qt::StrongFocus);setMouseTracking(true);collapsed={-1,-2};rebuild();}
void TimelineWidget::remapLayers(int from,int to){auto map=[&](int i){if(i==from)return to;if(from<to&&i>from&&i<=to)return i-1;if(from>to&&i>=to&&i<from)return i+1;return i;};for(auto&i:collapsed)i=map(i);active=map(active);}
double TimelineWidget::xAt(double t)const{return labelWidth+(t-viewStart)/viewSpan*std::max(1,width()-labelWidth-12);}
double TimelineWidget::timeAt(double x)const{return std::max(0.0,viewStart+(x-labelWidth)/std::max(1,width()-labelWidth-12)*viewSpan);}
double TimelineWidget::snap(double t)const{if(!snapping)return toSeconds(toTime(t));obs_video_info v{};if(obs_get_video_info(&v)&&v.fps_num&&v.fps_den)return std::round(t*v.fps_num/v.fps_den)*v.fps_den/v.fps_num;return t;}
int TimelineWidget::rowAt(double y)const{return firstRow+int((y-header)/rowHeight);}
void TimelineWidget::rebuild(){
 const int count=int(model->layers.size());collapsed.erase(std::remove_if(collapsed.begin(),collapsed.end(),[count](int i){return i>=count;}),collapsed.end());
 for(int i=knownLayers;i<count;++i)if(std::find(collapsed.begin(),collapsed.end(),i)==collapsed.end())collapsed.push_back(i);
 std::sort(collapsed.begin(),collapsed.end());collapsed.erase(std::unique(collapsed.begin(),collapsed.end()),collapsed.end());knownLayers=count;rows.clear();auto add=[&](int o,QString name){rows.push_back({o,"",name,true});if(std::find(collapsed.begin(),collapsed.end(),o)!=collapsed.end())return;for(const auto&p:parameters()){std::string id=p.id;if(o==-2&&id!="sx"&&id!="sy"&&id!="opacity")continue;if(o==-1&&(id=="sx"||id=="sy"||id=="opacity"))continue;if(o>=0&&(id=="fov"||id=="tx"||id=="ty"||id=="tz"||id=="radius"||id=="yaw"||id=="pitch"))continue;rows.push_back({o,id,u(p.label),false});}};add(-1,u("摄像机 · 视角"));add(-2,u("全画面合成"));for(size_t i=0;i<model->layers.size();++i)add(int(i),QString::fromStdString(layerDisplayName(model->layers[i])));firstRow=0;const int needed=std::max(220,header+int(rows.size())*rowHeight+2);if(minimumHeight()!=needed){setFixedHeight(needed);updateGeometry();}update();}
std::vector<KeyRef> TimelineWidget::keys(const Row&r)const{std::vector<KeyRef> result;auto&a=objectAnimation(*model,r.object);for(auto&pair:a){if(!r.summary&&pair.first!=r.param)continue;const auto&v=pair.second.keys();auto i=std::lower_bound(v.begin(),v.end(),toTime(viewStart),[](const auto&k,TimeUs t){return k.time<t;});for(;i!=v.end()&&i->time<=toTime(viewStart+viewSpan);++i)result.push_back({r.object,pair.first,i->time});}return result;}
void TimelineWidget::zoom(double factor,double anchor){if(anchor<0)anchor=width()*.6;double at=timeAt(anchor);viewSpan=std::clamp(viewSpan*factor,.01,9e12);viewStart=std::max(0.0,at-(anchor-labelWidth)/std::max(1,width()-labelWidth-12)*viewSpan);update();}
void TimelineWidget::pan(double seconds){viewStart=std::max(0.0,viewStart+seconds);update();}
void TimelineWidget::reveal(double t){if(t<viewStart||t>viewStart+viewSpan)viewStart=std::max(0.0,t-viewSpan*.2);update();}
void TimelineWidget::fit(){viewStart=0;viewSpan=std::max(6.0,toSeconds(contentEnd(*model))*1.05);update();}
void TimelineWidget::paintEvent(QPaintEvent*){
 QPainter p(this);p.setRenderHint(QPainter::Antialiasing);p.fillRect(rect(),QColor("#19222f"));p.fillRect(0,0,labelWidth,height(),QColor("#202b3b"));
 p.setPen(QColor("#b3c6dc"));p.drawText(8,21,u("对象 / 参数"));double raw=viewSpan/6,step=std::pow(10.0,std::floor(std::log10(raw)));if(raw/step>5)step*=10;else if(raw/step>2)step*=5;else if(raw/step>1)step*=2;
 for(double t=std::ceil(viewStart/step)*step;t<=viewStart+viewSpan;t+=step){int x=int(xAt(t));p.setPen(QColor("#344256"));p.drawLine(x,header,x,height());p.setPen(QColor("#c5d6ec"));QString text=t>=3600?QString::number(t/3600,'f',2)+"h":t>=60?QString::number(t/60,'f',2)+"m":QString::number(t,'f',step<1?3:1)+"s";p.drawText(QRect(x-35,2,70,26),Qt::AlignCenter,text);}
 p.save();p.setClipRect(labelWidth,header,width()-labelWidth,height()-header);for(auto t:candidates){double x=xAt(toSeconds(t));if(x<labelWidth||x>width())continue;p.setPen(QPen(QColor(125,156,190,100),1,Qt::DashLine));p.drawLine(QPointF(x,header),QPointF(x,height()));}p.restore();
 for(int i=firstRow;i<int(rows.size())&&header+(i-firstRow)*rowHeight<height();++i){const auto&r=rows[size_t(i)];int y=header+(i-firstRow)*rowHeight;if(r.object==active&&(parameter==r.param||r.summary))p.fillRect(0,y,width(),rowHeight,QColor("#304862"));p.setPen(QColor("#354356"));p.drawLine(0,y+rowHeight,width(),y+rowHeight);p.setPen(objectLocked(*model,r.object)?QColor("#84909d"):QColor("#deebf7"));QString name=(r.summary?(std::find(collapsed.begin(),collapsed.end(),r.object)!=collapsed.end()?u("▸ "):u("▾ ")):u("   "))+r.label+(r.summary&&objectLocked(*model,r.object)?u(" 🔒"):"");p.drawText(QRect(6,y,labelWidth-12,rowHeight),Qt::AlignVCenter,p.fontMetrics().elidedText(name,Qt::ElideRight,labelWidth-12));
  p.save();p.setClipRect(labelWidth,y,width()-labelWidth,rowHeight);for(const auto&k:keys(r)){bool selected=std::any_of(selection.begin(),selection.end(),[&](auto&s){return same(k,s);});TimeUs time=k.time+(dragging&&selected?delta:0);QPointF c(xAt(toSeconds(time)),y+rowHeight*.5);QPolygonF d;d<<c+QPointF(0,-5)<<c+QPointF(5,0)<<c+QPointF(0,5)<<c+QPointF(-5,0);p.setPen(selected?QColor("#fff2c0"):QColor("#e5b962"));p.setBrush(r.summary?Qt::NoBrush:QBrush(selected?QColor("#ffe2a0"):QColor("#d7a954")));p.drawPolygon(d);}p.restore();
 }
 if(reordering&&reorderTo>=0){auto it=std::find_if(rows.begin(),rows.end(),[&](const Row&r){return r.summary&&r.object==reorderTo;});if(it!=rows.end()){int y=header+(int(it-rows.begin())-firstRow)*rowHeight+(reorderTo>reorderFrom?rowHeight:0);p.setPen(QPen(QColor("#4cddce"),3));p.drawLine(22,y,width(),y);}}
 const double x=xAt(toSeconds(position));if(x>=labelWidth&&x<=width()){p.setPen(QPen(QColor("#4cddce"),2));p.drawLine(QPointF(x,27),QPointF(x,height()));}if(rubber){p.setPen(QPen(QColor("#81bbef"),1,Qt::DashLine));p.setBrush(QColor(80,130,200,30));p.drawRect(QRectF(origin,current).normalized());}
}
void TimelineWidget::mousePressEvent(QMouseEvent*e){setFocus();reorderFrom=reorderTo=-1;reordering=false;origin=current=e->position();if(e->button()==Qt::MiddleButton){panning=true;return;}if(e->button()!=Qt::LeftButton)return;if(origin.y()<header){position=toTime(snap(timeAt(origin.x())));if(seek)seek(position);dragging=false;return;}int n=rowAt(origin.y());if(n<0||size_t(n)>=rows.size())return;const auto&r=rows[size_t(n)];active=r.object;parameter=r.param;if(origin.x()<22&&r.summary){auto i=std::find(collapsed.begin(),collapsed.end(),r.object);if(i==collapsed.end())collapsed.push_back(r.object);else collapsed.erase(i);rebuild();return;}if(select)select(r.object,r.param);if(origin.x()<labelWidth){if(r.summary&&r.object>=0&&origin.x()>=22)reorderFrom=r.object;update();return;}
 std::vector<KeyRef> hit;for(auto&k:keys(r))if(std::abs(xAt(toSeconds(k.time))-origin.x())<8){hit.push_back(k);if(!r.summary)break;}
 if(hit.empty()){if(!(e->modifiers()&Qt::ControlModifier))selection.clear();rubber=true;update();return;}
 const auto t=hit.front().time;if(r.summary){hit.clear();for(const auto&pair:objectAnimation(*model,r.object))if(pair.second.contains(t))hit.push_back({r.object,pair.first,t});}
 bool already=std::any_of(selection.begin(),selection.end(),[&](auto&s){return same(s,hit.front());});if(!(e->modifiers()&(Qt::ControlModifier|Qt::ShiftModifier))&&!already)selection.clear();for(auto&k:hit)if(std::none_of(selection.begin(),selection.end(),[&](auto&s){return same(k,s);}))selection.push_back(k);
 position=t;delta=0;dragging=true;if(seek)seek(t);update();
}
void TimelineWidget::mouseMoveEvent(QMouseEvent*e){current=e->position();if(reorderFrom>=0&&(e->buttons()&Qt::LeftButton)){if(!reordering&&(current-origin).manhattanLength()>=QApplication::startDragDistance())reordering=true;if(reordering){int row=rowAt(current.y());reorderTo=row>=0&&size_t(row)<rows.size()&&rows[size_t(row)].object>=0?rows[size_t(row)].object:-1;update();}return;}if(panning){pan(-(current.x()-origin.x())*viewSpan/std::max(1,width()-labelWidth));origin=current;return;}if(dragging&&!model->keyPositionsLocked){delta=toTime(snap(timeAt(current.x())))-toTime(snap(timeAt(origin.x())));TimeUs minimum=INT64_MAX;for(auto&k:selection)minimum=std::min(minimum,k.time);delta=std::max(delta,-minimum);update();}else if(rubber)update();else if(e->buttons()&Qt::LeftButton&&origin.y()<header){position=toTime(snap(timeAt(current.x())));if(seek)seek(position);}}
void TimelineWidget::mouseReleaseEvent(QMouseEvent*){int from=reorderFrom,to=reorderTo;bool reordered=reordering;reorderFrom=reorderTo=-1;reordering=false;panning=false;if(reordered){dragging=rubber=false;delta=0;if(from>=0&&to>=0&&from!=to&&reorder)reorder(from,to);update();return;}if(dragging&&delta&&move)move(selection,delta);if(rubber){QRectF box=QRectF(origin,current).normalized();for(int i=firstRow;i<int(rows.size())&&header+(i-firstRow)*rowHeight<height();++i){const auto&r=rows[size_t(i)];if(r.summary)continue;for(auto&k:keys(r))if(box.contains(QPointF(xAt(toSeconds(k.time)),header+(i-firstRow+.5)*rowHeight)))if(std::none_of(selection.begin(),selection.end(),[&](auto&s){return same(k,s);}))selection.push_back(k);}}dragging=rubber=false;delta=0;setProperty("selectedKeyCount",int(selection.size()));update();if(select)select(active,parameter);}
void TimelineWidget::mouseDoubleClickEvent(QMouseEvent*e){if(e->position().x()<labelWidth)return;int i=rowAt(e->position().y());if(i<0||size_t(i)>=rows.size())return;active=rows[size_t(i)].object;parameter=rows[size_t(i)].param;if(select)select(active,parameter);if(seek)seek(toTime(snap(timeAt(e->position().x()))));if(record)record();}
void TimelineWidget::wheelEvent(QWheelEvent*e){if(e->modifiers()&Qt::ControlModifier)zoom(e->angleDelta().y()>0?.8:1.25,e->position().x());else if(e->modifiers()&Qt::ShiftModifier)pan(-e->angleDelta().y()/120.0*viewSpan*.12);else{e->ignore();return;}e->accept();}
bool TimelineWidget::event(QEvent*e){if(e->type()==QEvent::ShortcutOverride){auto*k=static_cast<QKeyEvent*>(e);if(k->key()==Qt::Key_Delete||k->matches(QKeySequence::Copy)||k->matches(QKeySequence::Paste)){e->accept();return true;}}return QWidget::event(e);}
void TimelineWidget::keyPressEvent(QKeyEvent*e){if(e->key()==Qt::Key_Delete&&remove)remove();else if(e->matches(QKeySequence::Copy)&&copy)copy();else if(e->matches(QKeySequence::Paste)&&paste)paste();else QWidget::keyPressEvent(e);}
